Context: This PR is related to task 1 in #10 

This PR implements two things.

1. ``BeanObject``, represent an MBean at the remote MBean server.
2. ``MBeanClient``, the client we used to fetch & query MBean from an MBean server.

### Code Example

```java
package org.astraea;

import java.util.Set;
import javax.management.remote.JMXServiceURL;
import org.astraea.metrics.jmx.BeanObject;
import org.astraea.metrics.jmx.BeanQuery;
import org.astraea.metrics.jmx.MBeanClient;

public class Ignore {
  public static String JMX_URI_FORMAT =
      "service:jmx:rmi:///jndi/rmi://" + "%s" + ":" + "%d" + "/jmxrmi";

  public static String createJmxUrl(String hostname, String port) {
    return String.format(JMX_URI_FORMAT, hostname, Integer.parseInt(port));
  }

  public static void main(String[] args) throws Exception {
    JMXServiceURL jmxServiceURL = new JMXServiceURL(createJmxUrl("localhost", "19835"));
    MBeanClient client = new MBeanClient(jmxServiceURL);
    client.connect();

    BeanObject fetchResult =
        client.fetchObjectAttribute(
            BeanObject.fromDomainName("java.lang")
                .selectProperty("type", "Memory")
                .fetchAttribute("HeapMemoryUsage")
                .fetchAttribute("NonHeapMemoryUsage"));

    fetchResult
        .getAttributeView()
        .forEach(
            (key, value) -> {
              System.out.printf("%s: %s%n", key, value);
            });

    Set<BeanObject> beanObjects =
        client.queryObject(
            BeanQuery.forDomainName("kafka.network")
                .whereProperty("type", "RequestMetrics")
                .whereProperty("request", "Delete*")
                .whereProperty("name", "LocalTimeMs"));

    System.out.printf("%nQuery Result:%n");
    beanObjects.forEach(
        bean -> {
          System.out.printf("%s%n", bean.objectName());
        });

    client.close();
  }
}
```

