This is a large change to how you retrieve values from the cache from actions to make it more declarative.

Before:

```js
const store = new Store({ count: 42 })
store.useMiddleware(promiseMiddleware())

const increment = () => ({
  name: 'increment',
  payload: (cache) => ({
    count: cache.get('count') + 1
  }
})

store.dispatch(increment())
```

After:

```js
const store = new Store({ count: 42 })
store.useMiddleware(functionMiddleware())

const increment = (id) => ({
  name: 'increment',
  inputs: { count: 'count' },
  payload: ({ count }) => ({
    count: count + 1
  }
})

store.dispatch(increment())
```

